// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 internal depositCounter;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 numCalls, uint256[] calldata values) public {
        numCalls = bound(numCalls, 1, 50);

        vm.assume(values.length >= numCalls);

        depositCounter = 0;

        for (uint256 i = 0; i < numCalls; i++) {
            uint256 val = bound(values[i], 1, 100 ether);
            vm.deal(address(this), val);
            (bool ok,) = address(c).call{value: val}("");
            assertTrue(ok, "receive reverted unexpectedly");
            depositCounter++;
        }

        assertEq(c.depositsCount(), depositCounter);
    }
}
